use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::String(s) = input {
        let hex_str = s.as_str().unwrap();
        let bytes = hex_str.chars().map(|c| c.to_digit(16).unwrap() as u8).collect();
        Value::Array(bytes.into_iter().map(|b| Value::Number(serde_json::Number::from(b))).collect())
    } else {
        Value::Null
    }
}
